package com.tekwatt.notification.controller;import com.tekwatt.notification.dto.*;import com.tekwatt.notification.service.NotificationService;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/notifications")public class NotificationController{private final NotificationService service;public NotificationController(NotificationService s){service=s;}@PostMapping@ResponseStatus(HttpStatus.CREATED)NotificationResponse create(@Valid@RequestBody CreateNotificationRequest r){return service.create(r);}@GetMapping("/{id}")NotificationResponse get(@PathVariable UUID id){return service.get(id);}@GetMapping List<NotificationResponse>list(@RequestParam UUID tenantId){return service.list(tenantId);}@PostMapping("/{id}/send")NotificationResponse send(@PathVariable UUID id){return service.send(id);}@PatchMapping("/{id}/result")NotificationResponse result(@PathVariable UUID id,@Valid@RequestBody DeliveryResultRequest r){return service.result(id,r);}@PostMapping("/{id}/retry")NotificationResponse retry(@PathVariable UUID id){return service.retry(id);}}
